INSERT INTO public.science_lessons (id, module_id, title, slug, summary, lesson_kind, estimated_minutes, xp_reward, order_index, is_required, is_published) VALUES
  ('50cd9737-d05b-5496-913c-eadfda609dd9', '0ff6c122-b71e-510d-a43a-a9e8ce6e97a3', 'Course record and learning cycle', 'orientation', 'Understand the course standard, learning cycle, error categories, and formative assessment model.', 'concept', 25, 15, 0, true, true),
  ('acac67e4-61b6-55ee-96c4-3dcdc8af6b26', '0ff6c122-b71e-510d-a43a-a9e8ce6e97a3', 'Part 0 - Mathematical and Experimental Foundations', 'mathematical-foundations', 'A recommended readiness reference for units, vectors, calculus, graphs, computation, measurement, and uncertainty.', 'concept', 90, 15, 1, true, true),
  ('1f5a3d58-a0cc-5ddb-aba9-2bec780d01c6', '5e4469bb-ac60-5918-b6f4-40cb2c44064f', '1.1 Models, coordinates, and the language of motion', 'models-and-coordinates', 'Controlled abstraction, coordinates, displacement, distance, velocity, and speed.', 'concept', 120, 25, 0, true, true),
  ('935a1404-9ea3-5169-82b4-fcd08179c0cd', '5e4469bb-ac60-5918-b6f4-40cb2c44064f', '1.2 Instantaneous velocity, acceleration, and constant-acceleration kinematics', 'velocity-and-kinematics', 'Slopes, areas, signs, and the limited domain of constant-acceleration equations.', 'concept', 120, 25, 1, true, true),
  ('7dc5ff56-0944-5e47-9923-77f9c03db7af', '5e4469bb-ac60-5918-b6f4-40cb2c44064f', '1.3 Vectors, components, and projectile motion', 'vectors-and-projectiles', 'Decompose vectors and connect independent horizontal and vertical projectile motion.', 'concept', 120, 25, 2, true, true),
  ('627696e8-d4b1-5d88-92bc-18922e7859f8', '5e4469bb-ac60-5918-b6f4-40cb2c44064f', '1.4 Newton''s laws and free-body diagrams', 'newtons-laws-and-fbds', 'Inertial frames, momentum, net force, interactions, and system isolation.', 'concept', 150, 25, 3, true, true),
  ('abfc1226-0daf-59da-9d27-028e79a3fe0d', '5e4469bb-ac60-5918-b6f4-40cb2c44064f', '1.5 Common forces and a repeatable solution method', 'common-forces-and-method', 'Weight, normal force, tension, springs, and a reusable modelling sequence.', 'concept', 150, 25, 4, true, true),
  ('adaa6eeb-6eca-5fc6-a52c-30080da2d297', '5e4469bb-ac60-5918-b6f4-40cb2c44064f', 'Guided Exercises 1A and 1B', 'guided-exercises', 'Reconstruct motion from a graph and practise system-specific free-body diagrams.', 'practice', 180, 25, 5, true, true),
  ('cdc3d5f3-5e04-5eec-ae9f-3f92f9b155fd', '5e4469bb-ac60-5918-b6f4-40cb2c44064f', 'Module 1 - Interactive Deepening', 'tutorial-studio', 'Derivation practice, worked-example studios, tutorials, and error diagnosis.', 'practice', 360, 25, 6, true, true),
  ('09ab2235-36bf-541b-b1e6-d472e8844eb7', '5e4469bb-ac60-5918-b6f4-40cb2c44064f', 'Experimental and computational investigation', 'investigation', 'Track real motion and integrate measured acceleration numerically.', 'lab', 360, 25, 7, true, true),
  ('d562b56f-ed6d-58a1-b02c-066a037ae26c', '5e4469bb-ac60-5918-b6f4-40cb2c44064f', 'Module 1 problem set', 'problem-set', 'Ten less-scaffolded problems requiring representations, units, and checks.', 'practice', 360, 25, 8, true, true),
  ('2f483580-6047-5b67-9803-5be6f4845b7f', '5e4469bb-ac60-5918-b6f4-40cb2c44064f', 'Module mastery and quiz', 'mastery-and-quiz', 'Two closed-note formative assessments with six objective and two constructed items each.', 'quiz', 55, 25, 9, true, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('5e4fc047-f1cb-571d-843c-ec517864c64e', '50cd9737-d05b-5496-913c-eadfda609dd9', 'callout', 'Orientation', '{"variant":"intuition","body":"**Learning outcomes**\n- Explain the scientific standard used throughout the course.\n- Use the eight-stage module learning cycle.\n- Classify model, representation, mathematical, and interpretation errors.\n\n**Essential questions**\n- What makes a numerical result scientifically traceable?"}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('5e4fc047-f1cb-571d-843c-ec517864c64e', '50cd9737-d05b-5496-913c-eadfda609dd9', 'rich_text', 'Publication and Course Record', '{"body":"This edition expands the existing PHY111 coursebook while retaining its twelve-module scientific sequence. The original course already contains 24 guided exercises, 36 worked examples, twelve module quizzes, a study guide, and a formative key. Version 2.1 adds a substantial interactive layer designed around prediction, representation, derivation, experimental evidence, computation, error diagnosis, and cumulative mastery.\n\n**Level:** Calculus-based undergraduate foundation\n\n**Recommended workload:** 350-450 hours including exposition, derivations, tutorials, problem sets, laboratory or simulation work, computational activities, formal coursework, and revision.\n\n**Primary scope source:** Robert G. Brown, *Introductory Physics I: Elementary Mechanics*, Duke University Physics Department.\n\n**Scientific standard:** Every numerical result must be traceable to an explicit model, units, assumptions, and a check; computation is a method, not a substitute for modelling.\n\n### What Version 2.1 adds\n\n- 24 expanded tutorial workshops\n- 24 additional worked-example studios\n- 12 experimental or simulation investigations\n- 12 computational mini-labs\n- 12 error-diagnosis tasks\n- 120 additional unguided problems\n- 12 additional mastery tests\n- Four cumulative progress examinations\n- Six formal assessed projects\n- A new three-hour final examination\n- A calculator-ready exam formula sheet\n- An expanded instructor solutions and marking guide"}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('5e4fc047-f1cb-571d-843c-ec517864c64e', '50cd9737-d05b-5496-913c-eadfda609dd9', 'rich_text', 'From Motion to Field - Expanded Learning Cycle', '{"body":"The course is cumulative. Each new method is introduced as a response to a limitation in the previous description: kinematics becomes dynamics; particle dynamics becomes system conservation; translation becomes rotation; discrete bodies become continuous matter; oscillation becomes wave propagation; and local force models become a gravitational field description.\n\n### The module learning cycle\n\n1. **Orient.** Read the module question and outcomes. Attempt the short diagnostic from memory.\n2. **Build.** Study definitions and derivations. Reproduce each important derivation without looking.\n3. **Represent.** Draw graphs, vectors, free-body diagrams, energy diagrams, or field sketches before algebra.\n4. **Solve.** Cover worked solutions and solve first. Compare method, not only the final number.\n5. **Tutorial.** Complete the expanded workshop prompts in order: prediction -> representation -> derivation -> calculation -> interpretation.\n6. **Investigate.** Perform the experiment, simulation, or computational activity and compare evidence with the ideal model.\n7. **Stress-test.** Debug a deliberately flawed solution and solve the less-scaffolded problem set.\n8. **Assess.** Take the module mastery test closed-notes, then review errors by category.\n\n### Error categories\n\n- **Model error:** Wrong system, frame, approximation, omitted interaction, or unjustified conservation law.\n- **Representation error:** Graph, vector, sign convention, free-body diagram, or geometry does not match the physical situation.\n- **Mathematical error:** Algebra, calculus, trigonometry, numerical integration, or unit conversion mistake.\n- **Interpretation error:** Number is calculated correctly but physical meaning, direction, limiting case, or uncertainty is wrong."}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('5e4fc047-f1cb-571d-843c-ec517864c64e', '50cd9737-d05b-5496-913c-eadfda609dd9', 'rich_text', 'Knowledge Testing in a Physics Course', '{"body":"**Concept checks.** Short qualitative prompts interrupt passive reading and force a prediction before calculation.\n\n**Worked-example cover method.** Read only the problem, hide the solution, solve independently, then compare the modelling path line by line.\n\n**Tutorial workshops.** Structured multi-step problems require diagrams, symbolic derivation, limiting cases, and explanation.\n\n**Experiments and simulations.** Students must confront measurement uncertainty, non-ideal behaviour, numerical error, and the gap between model and evidence.\n\n**Error diagnosis.** Deliberately flawed solutions test whether the learner can locate the first invalid inference instead of merely spotting a wrong answer.\n\n**Mastery tests.** Closed-note module tests and cumulative progress exams require retrieval under time pressure.\n\n### Formal weighting\n\nFormative work in the coursebook is ungraded. Six formal assignments contribute 60 percent of the course result. The cumulative final examination contributes 40 percent. Four progress examinations are provided for timed practice and diagnostic use but do not alter the formal weighting unless an institution adopts a different scheme. The public beta implements Module 1 as formative practice only and does not award a formal course result."}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('5e4fc047-f1cb-571d-843c-ec517864c64e', '50cd9737-d05b-5496-913c-eadfda609dd9', 'constructed_response', 'Scientific standard acknowledgement', '{"prompt":"Every numerical result must be traceable to an explicit model, units, assumptions, and a check; computation is a method, not a substitute for modelling.\n\nIn your own words, confirm the standard and how you will apply it:","modelAnswer":"I will show the model, units, assumptions, and at least one check.","rubric":[],"minChars":10}'::jsonb, '{"min_chars":10}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('5e4fc047-f1cb-571d-843c-ec517864c64e', '50cd9737-d05b-5496-913c-eadfda609dd9', 'constructed_response', 'Reflection', '{"prompt":"- Which error category currently causes you the most difficulty?","rubric":[],"minChars":20}'::jsonb, '{"min_chars":20}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('3be340ef-9a80-5db6-b1ba-db70c8fb2b05', 'acac67e4-61b6-55ee-96c4-3dcdc8af6b26', 'callout', 'Orientation', '{"variant":"intuition","body":"**Learning outcomes**\n- Check dimensions and estimate orders of magnitude.\n- Use vector components and calculus as physical operations.\n- Report numerical work and measurements with validation and uncertainty.\n\n**Essential questions**\n- How do mathematical operations encode physical meaning?"}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('3be340ef-9a80-5db6-b1ba-db70c8fb2b05', 'acac67e4-61b6-55ee-96c4-3dcdc8af6b26', 'rich_text', 'Mathematical and Experimental Foundations', '{"body":"### 0.1 Units, dimensions, and order of magnitude\n\nA physical equation must be dimensionally homogeneous. Unit checking is not cosmetic: it is one of the fastest ways to discover a missing factor of time, length, mass, or angle. Before evaluating a formula, write dimensions symbolically and estimate the expected order of magnitude.\n\n### 0.2 Vectors and components\n\nA vector is independent of coordinates; its components depend on the chosen basis. Resolve vectors only after choosing axes that simplify the geometry. Dot products encode projection and work; cross products encode oriented area, torque, and angular momentum.\n\n$$\\vec A\\cdot\\vec B=AB\\cos\\theta,\\qquad |\\vec A\\times\\vec B|=AB\\sin\\theta$$\n\n### 0.3 Derivatives and integrals as physical operations\n\nThe derivative gives a local rate of change; the integral accumulates a rate over an interval. Kinematics therefore provides the first recurring calculus chain: $x(t) \\rightarrow v(t) \\rightarrow a(t)$ by differentiation and $a(t) \\rightarrow \\Delta v \\rightarrow \\Delta x$ by integration.\n\n### 0.4 Graphs as equations you can see\n\nSlope and area are physical information. A graph should display axes, units, sign, scale, and uncertainty where applicable. Before using a calculator, sketch the expected graph shape from the physics.\n\n### 0.5 Numerical computation\n\nNumerical work is appropriate when an equation cannot be solved conveniently in closed form, when data are sampled, or when a model is being simulated. A computational result is incomplete without initial conditions, parameter values, units, algorithm, step size or tolerance, and a validation test against a known limit.\n\n**Minimum numerical validation:** Run at least one case with a known analytic answer, repeat with a smaller time step, and verify conserved quantities when the model predicts conservation.\n\n### 0.6 Measurement and uncertainty\n\nMeasurements are estimates, not exact mathematical objects. Distinguish instrument resolution, random scatter, systematic calibration error, and model error. Report enough significant figures to reflect the evidence rather than the calculator display."}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('3be340ef-9a80-5db6-b1ba-db70c8fb2b05', 'acac67e4-61b6-55ee-96c4-3dcdc8af6b26', 'constructed_response', 'Foundation practice: dimensions', '{"prompt":"- Show that the dimensions of energy are M L² T⁻².\n- Show that the dimensions of power are M L² T⁻³.\n- Show that v²/g has dimensions of length.","guidance":null,"modelAnswer":null,"rubric":[{"id":"r0","label":"Every term uses base dimensions."},{"id":"r1","label":"The final dimension matches the requested physical quantity."}],"minChars":12}'::jsonb, '{"min_chars":12}'::jsonb, 0, true)
