INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('3be340ef-9a80-5db6-b1ba-db70c8fb2b05', 'acac67e4-61b6-55ee-96c4-3dcdc8af6b26', 'constructed_response', 'Reflection', '{"prompt":"- Which foundation should you review before continuing?","rubric":[],"minChars":20}'::jsonb, '{"min_chars":20}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('74e8fe51-4c42-5ca9-84ef-554a20d01ab1', '1f5a3d58-a0cc-5ddb-aba9-2bec780d01c6', 'callout', 'Orientation', '{"variant":"intuition","body":"**Learning outcomes**\n- Choose a model and coordinate system.\n- Distinguish distance from displacement.\n- Distinguish average speed from average velocity.\n\n**Essential questions**\n- How does physics turn motion into a quantitative model?"}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('74e8fe51-4c42-5ca9-84ef-554a20d01ab1', '1f5a3d58-a0cc-5ddb-aba9-2bec780d01c6', 'rich_text', 'Module launch and Section 1.1', '{"body":"## Module 1 - Newtonian Description of Motion and Force\n\n*Coordinates, vectors, free-body diagrams, and Newton''s laws*\n\n> How does physics turn motion into a quantitative model?\n\nA free-body diagram isolates one object and displays only the external forces acting on it.\n\n### 1.1 Models, coordinates, and the language of motion\n\nPhysics begins by replacing an overwhelmingly detailed event with a deliberately limited model. A moving car can be treated as a particle when its size and rotation do not matter; Earth can be treated as a uniform gravitational field when the height change is small compared with Earth''s radius. A good model is not a photograph of reality. It is a controlled abstraction that preserves the features needed to answer a question.\n\nA coordinate system gives numerical meaning to location. In one dimension, a signed coordinate $x$ distinguishes positions on opposite sides of an origin. In two or three dimensions, a position vector identifies a point relative to the chosen origin. The origin and positive directions are choices, not properties of nature, so changing them may change the signs of components without changing the physical event.\n\nDisplacement is the change in position and therefore depends only on the endpoints. Distance is the length of the path and is never negative. Average velocity is displacement divided by elapsed time; average speed is distance divided by elapsed time. This distinction is already a test of disciplined modeling: a runner who returns to the start has traveled a nonzero distance but has zero displacement.\n\n$$\\Delta x=x_f-x_i,\\qquad \\bar v=\\frac{\\Delta x}{\\Delta t},\\qquad \\bar a=\\frac{\\Delta v}{\\Delta t}$$"}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('74e8fe51-4c42-5ca9-84ef-554a20d01ab1', '1f5a3d58-a0cc-5ddb-aba9-2bec780d01c6', 'constructed_response', 'Concept check 1.1', '{"prompt":"- Why can a coordinate be negative while a distance cannot?\n- Which quantities change if the positive axis is reversed?","guidance":null,"modelAnswer":null,"rubric":[{"id":"r0","label":"I distinguished a coordinate from a path length."},{"id":"r1","label":"I distinguished vector components from scalar quantities."}],"minChars":12}'::jsonb, '{"min_chars":12}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('74e8fe51-4c42-5ca9-84ef-554a20d01ab1', '1f5a3d58-a0cc-5ddb-aba9-2bec780d01c6', 'worked_example_studio', 'Worked example: A round trip with unequal speeds', '{"problem":"A student walks 120 m east in 80 s and then 120 m west in 120 s. Find average velocity and average speed.","prompt":"Attempt the problem before revealing the complete source solution.","steps":["1. Choose east as positive. The total displacement is +120 m - 120 m = 0.","2. The elapsed time is 200 s, so the average velocity is 0/200 = 0 m s⁻¹.","3. The total distance is 240 m, so average speed is 240/200 = 1.20 m s⁻¹."],"answer":"Average velocity = 0; average speed = 1.20 m s⁻¹.","interpretation":"The same journey can have zero average velocity and a positive average speed because velocity records net change, while speed records accumulated path length."}'::jsonb, '{"min_attempt_chars":10}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('74e8fe51-4c42-5ca9-84ef-554a20d01ab1', '1f5a3d58-a0cc-5ddb-aba9-2bec780d01c6', 'constructed_response', 'Reflection', '{"prompt":"- Which sign conventions did you choose, and why?","rubric":[],"minChars":20}'::jsonb, '{"min_chars":20}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('e36ed2bf-53b5-5ed0-9cb9-cf410f369521', '935a1404-9ea3-5169-82b4-fcd08179c0cd', 'callout', 'Orientation', '{"variant":"intuition","body":"**Learning outcomes**\n- Interpret derivatives and areas on motion graphs.\n- Apply constant-acceleration equations only when valid.\n- Use velocity and acceleration signs correctly.\n\n**Essential questions**\n- Why are constant-acceleration equations special cases rather than independent laws?"}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('e36ed2bf-53b5-5ed0-9cb9-cf410f369521', '935a1404-9ea3-5169-82b4-fcd08179c0cd', 'rich_text', 'Instantaneous motion and constant acceleration', '{"body":"The instantaneous velocity is the limiting slope of the position-time graph as the time interval shrinks. Acceleration is the limiting slope of the velocity-time graph. These graphical meanings are more fundamental than any memorized kinematic formula: the slope of $x(t)$ is $v(t)$, and the area under $v(t)$ is displacement.\n\nFor constant acceleration, velocity changes linearly with time and position changes quadratically. The familiar kinematic equations are not separate laws of nature; they are consequences of the definitions of velocity and acceleration under the special assumption that acceleration is constant. They must not be used uncritically when acceleration depends on time, position, or velocity.\n\nSigns carry physical meaning. A negative velocity means motion in the negative coordinate direction. A negative acceleration means the velocity is changing toward the negative direction; it does not automatically mean that an object is slowing down. An object speeds up when velocity and acceleration have the same sign and slows down when their signs differ.\n\n$$v_f=v_i+at$$\n\n$$\\Delta x=v_it+\\tfrac12at^2$$\n\n$$v_f^2=v_i^2+2a\\Delta x$$"}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('e36ed2bf-53b5-5ed0-9cb9-cf410f369521', '935a1404-9ea3-5169-82b4-fcd08179c0cd', 'constructed_response', 'Concept check 1.2', '{"prompt":"- Can velocity be zero while acceleration is nonzero? Give an example.\n- What feature of a velocity-time graph gives displacement?","guidance":null,"modelAnswer":null,"rubric":[{"id":"r0","label":"My example identifies an instant rather than an interval."},{"id":"r1","label":"I used signed area rather than only geometric area."}],"minChars":12}'::jsonb, '{"min_chars":12}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('e36ed2bf-53b5-5ed0-9cb9-cf410f369521', '935a1404-9ea3-5169-82b4-fcd08179c0cd', 'worked_example_studio', 'Worked example: Braking to rest', '{"problem":"A bicycle travels at 8.0 m s⁻¹ and brakes with constant acceleration -2.0 m s⁻². Find the stopping time and distance.","prompt":"Attempt the stopping problem before revealing the source solution.","steps":["1. Set v_f=0. From v_f=v_i+at, t=(0-8.0)/(-2.0)=4.0 s.","2. Use Δx=v_it+½at²=8.0(4.0)+½(-2.0)(4.0)².","3. The displacement is 32-16=16 m."],"answer":"Stopping time = 4.0 s; stopping distance = 16 m.","interpretation":"Doubling the initial speed while keeping the same braking acceleration would quadruple the braking distance."}'::jsonb, '{"min_attempt_chars":10}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('e36ed2bf-53b5-5ed0-9cb9-cf410f369521', '935a1404-9ea3-5169-82b4-fcd08179c0cd', 'constructed_response', 'Reflection', '{"prompt":"- How can an object have zero velocity and nonzero acceleration?","rubric":[],"minChars":20}'::jsonb, '{"min_chars":20}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('425a75f5-6b8d-5826-a7fc-f7a84e6710fc', '7dc5ff56-0944-5e47-9923-77f9c03db7af', 'callout', 'Orientation', '{"variant":"intuition","body":"**Learning outcomes**\n- Resolve a vector into components.\n- Model ideal projectile motion.\n- State the assumptions behind a parabolic trajectory.\n\n**Essential questions**\n- How can one two-dimensional motion become two coupled one-dimensional descriptions?"}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('425a75f5-6b8d-5826-a7fc-f7a84e6710fc', '7dc5ff56-0944-5e47-9923-77f9c03db7af', 'rich_text', 'Vectors, components, and projectile motion', '{"body":"A vector has magnitude and direction. It can be represented geometrically by an arrow or algebraically by components. Components are not independent physical objects; they are the projections of one vector onto chosen axes. Because perpendicular components can be treated separately and recombined, vector decomposition converts many two-dimensional problems into paired one-dimensional problems.\n\nProjectile motion near Earth is the motion of an object after launch when air resistance is neglected. Horizontal acceleration is zero, while vertical acceleration is approximately constant and downward. The horizontal and vertical motions share the same time but otherwise evolve independently. This is why a horizontally launched object and a simultaneously dropped object reach level ground at the same time, provided they begin at the same height.\n\nThe trajectory is parabolic only under the ideal assumptions of constant downward acceleration, flat ground, and no drag. Real projectiles deviate because gravity varies slightly, air exerts forces, and Earth rotates, but the ideal model is powerful because it isolates the dominant structure.\n\n$$A_x=A\\cos\\theta,\\qquad A_y=A\\sin\\theta$$\n\n$$x(t)=x_0+v_0\\cos\\theta\\,t$$\n\n$$y(t)=y_0+v_0\\sin\\theta\\,t-\\tfrac12gt^2$$"}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('425a75f5-6b8d-5826-a7fc-f7a84e6710fc', '7dc5ff56-0944-5e47-9923-77f9c03db7af', 'constructed_response', 'Concept check 1.3', '{"prompt":"- Why is the horizontal velocity constant in the ideal projectile model?\n- Which launch angles give the same range on level ground when drag is absent?","guidance":null,"modelAnswer":null,"rubric":[{"id":"r0","label":"I identified the zero-horizontal-force assumption."},{"id":"r1","label":"I related complementary angles through sin(2θ)."}],"minChars":12}'::jsonb, '{"min_chars":12}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('425a75f5-6b8d-5826-a7fc-f7a84e6710fc', '7dc5ff56-0944-5e47-9923-77f9c03db7af', 'worked_example_studio', 'Worked example: Launch from level ground', '{"problem":"A ball is launched at 20 m s⁻¹ at 30° above horizontal. Neglect air resistance and take g=9.8 m s⁻². Find flight time and range.","prompt":"Attempt the projectile problem before revealing the source solution.","steps":["1. Resolve the initial velocity: v₀x=20 cos30°=17.3 m s⁻¹; v₀y=20 sin30°=10.0 m s⁻¹.","2. At landing y-y₀=0, so 0=v₀yt-½gt². The nonzero solution is t=2v₀y/g=2.04 s.","3. Range R=v₀xt=17.3(2.04)=35.3 m."],"answer":"Flight time ≈ 2.04 s; range ≈ 35.3 m.","interpretation":"The vertical component determines how long the projectile remains aloft; the horizontal component converts that time into range."}'::jsonb, '{"min_attempt_chars":10}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('425a75f5-6b8d-5826-a7fc-f7a84e6710fc', '7dc5ff56-0944-5e47-9923-77f9c03db7af', 'constructed_response', 'Reflection', '{"prompt":"- Which projectile assumptions are least realistic in your chosen situation?","rubric":[],"minChars":20}'::jsonb, '{"min_chars":20}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('4097ae73-d7e7-56de-9f72-f91bdd515e18', '627696e8-d4b1-5d88-92bc-18922e7859f8', 'callout', 'Orientation', '{"variant":"intuition","body":"**Learning outcomes**\n- Identify an inertial frame.\n- Construct a valid free-body diagram.\n- Distinguish third-law partners from balanced forces.\n\n**Essential questions**\n- Why is a free-body diagram the bridge between a situation and an equation?"}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('4097ae73-d7e7-56de-9f72-f91bdd515e18', '627696e8-d4b1-5d88-92bc-18922e7859f8', 'rich_text', 'Newton''s laws and free-body diagrams', '{"body":"Newton''s first law identifies inertial reference frames: frames in which an object with zero net force maintains constant velocity. The law is not merely the special case $F=0$ of the second law; it specifies the kind of frame in which the standard form of the second law is valid.\n\nNewton''s second law states that the vector sum of external forces on an object equals the time rate of change of its momentum. For constant mass this becomes $\\sum \\vec F=m\\vec a$. The acceleration points in the direction of the net force, not necessarily in the direction of the velocity. A free-body diagram is the bridge between the physical situation and this equation.\n\nNewton''s third law concerns interactions: if object A exerts a force on B, B simultaneously exerts an equal-magnitude, opposite-direction force on A. Third-law partners act on different objects and therefore never cancel on one object''s free-body diagram. Weight and normal force are often equal in magnitude, but they are not a third-law pair.\n\n$$\\sum\\vec F=\\frac{d\\vec p}{dt},\\qquad \\sum\\vec F=m\\vec a,\\qquad \\vec F_{A\\to B}=-\\vec F_{B\\to A}$$"}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('4097ae73-d7e7-56de-9f72-f91bdd515e18', '627696e8-d4b1-5d88-92bc-18922e7859f8', 'constructed_response', 'Concept check 1.4', '{"prompt":"- Why must every force on a free-body diagram have an identifiable source?\n- Why do third-law forces not cancel in the equation for a single object?","guidance":null,"modelAnswer":null,"rubric":[{"id":"r0","label":"Every force is tied to an interaction."},{"id":"r1","label":"I stated that third-law partners act on different objects."}],"minChars":12}'::jsonb, '{"min_chars":12}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('4097ae73-d7e7-56de-9f72-f91bdd515e18', '627696e8-d4b1-5d88-92bc-18922e7859f8', 'worked_example_studio', 'Worked example: Two blocks pulled together', '{"problem":"Blocks of 2.0 kg and 3.0 kg are connected by a light cord on a frictionless table. A 20 N horizontal force pulls the 3.0 kg block. Find the acceleration and cord tension.","prompt":"Attempt the connected-system problem before revealing the source solution.","steps":["1. Treat both blocks as one system: a=F/(m₁+m₂)=20/5.0=4.0 m s⁻².","2. Isolate the 2.0 kg block. Its only horizontal force is the tension T.","3. Apply T=m₁a=2.0(4.0)=8.0 N."],"answer":"Acceleration = 4.0 m s⁻²; tension = 8.0 N.","interpretation":"Choosing the entire system first eliminates the internal tension; isolating one block afterward reveals it."}'::jsonb, '{"min_attempt_chars":10}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('4097ae73-d7e7-56de-9f72-f91bdd515e18', '627696e8-d4b1-5d88-92bc-18922e7859f8', 'constructed_response', 'Reflection', '{"prompt":"- What source produces each force in your diagram?","rubric":[],"minChars":20}'::jsonb, '{"min_chars":20}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('30ed3389-d88a-5a61-8eb1-72f45267563a', 'abfc1226-0daf-59da-9d27-028e79a3fe0d', 'callout', 'Orientation', '{"variant":"intuition","body":"**Learning outcomes**\n- Identify common forces and their sources.\n- Apply a repeatable Newtonian solution sequence.\n- Check units, signs, limiting cases, and magnitude.\n\n**Essential questions**\n- What must be checked after a force problem is solved?"}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('30ed3389-d88a-5a61-8eb1-72f45267563a', 'abfc1226-0daf-59da-9d27-028e79a3fe0d', 'rich_text', 'Common forces and a repeatable solution method', '{"body":"Near Earth, weight is the gravitational force $mg$. A normal force is a contact force perpendicular to a surface; it is not automatically equal to weight. Tension is the force transmitted by an ideal light cord and acts away from the object along the cord. Spring force is approximately proportional and opposite to displacement from equilibrium. Friction and drag require additional models developed in Module 2.\n\nA reliable Newtonian solution follows a fixed sequence: define the system; choose axes; draw the free-body diagram; translate the diagram into component equations; solve symbolically when possible; then inspect units, signs, limiting cases, and magnitude. Skipping the diagram often produces missing forces or forces assigned to the wrong object.\n\nThe final numerical value is not the whole answer. A negative result may indicate a direction opposite to the assumed positive axis rather than an error. An impossible limiting case, wrong unit, or acceleration wildly inconsistent with the available force signals a model or algebra mistake.\n\n$$W=mg,\\qquad F_s=-kx$$"}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('30ed3389-d88a-5a61-8eb1-72f45267563a', 'abfc1226-0daf-59da-9d27-028e79a3fe0d', 'constructed_response', 'Concept check 1.5', '{"prompt":"- When can a normal force be smaller than, equal to, or larger than weight?\n- What checks should be performed after solving a force problem?","guidance":null,"modelAnswer":null,"rubric":[{"id":"r0","label":"I related the normal force to contact constraints, not a fixed rule."},{"id":"r1","label":"I checked units, signs, limiting cases, and physical magnitude."}],"minChars":12}'::jsonb, '{"min_chars":12}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('30ed3389-d88a-5a61-8eb1-72f45267563a', 'abfc1226-0daf-59da-9d27-028e79a3fe0d', 'worked_example_studio', 'Worked example: Apparent weight in an elevator', '{"problem":"A 70 kg person stands on a scale in an elevator accelerating upward at 1.5 m s⁻². What does the scale read?","prompt":"Attempt the force problem before revealing the source solution.","steps":["1. For the person, choose upward positive. Forces are normal force N upward and weight mg downward.","2. Newton''s second law gives N-mg=ma.","3. Thus N=m(g+a)=70(9.8+1.5)=791 N."],"answer":"Scale reading = 7.9 × 10² N.","interpretation":"The scale measures the normal force, not gravity directly. Upward acceleration makes the apparent weight exceed mg."}'::jsonb, '{"min_attempt_chars":10}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('30ed3389-d88a-5a61-8eb1-72f45267563a', 'abfc1226-0daf-59da-9d27-028e79a3fe0d', 'constructed_response', 'Reflection', '{"prompt":"- When can a normal force differ from weight?","rubric":[],"minChars":20}'::jsonb, '{"min_chars":20}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('ea620ed5-c5d0-516c-b965-3534d21eae27', 'adaa6eeb-6eca-5fc6-a52c-30080da2d297', 'callout', 'Orientation', '{"variant":"intuition","body":"**Learning outcomes**\n- Use signed graph area and slope.\n- Construct four separate free-body diagrams.\n- Identify third-law partners outside each diagram.\n\n**Essential questions**\n- How must one representation constrain another?"}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('ea620ed5-c5d0-516c-b965-3534d21eae27', 'adaa6eeb-6eca-5fc6-a52c-30080da2d297', 'rich_text', 'Guided Exercises', '{"body":"Complete the reconstruction before consulting the separate instructor guide. Diagrams, assumptions, units, and interpretation are part of the solution."}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('ea620ed5-c5d0-516c-b965-3534d21eae27', 'adaa6eeb-6eca-5fc6-a52c-30080da2d297', 'graph_table_lab', 'Exercise 1A - Motion reconstruction', '{"instructions":"A particle''s velocity is +4 m s⁻¹ from 0-3 s, decreases linearly to -2 m s⁻¹ from 3-6 s, and remains -2 m s⁻¹ from 6-9 s. Draw the velocity-time graph, calculate total displacement, identify turning time, and sketch a compatible position-time graph.","columns":[{"key":"time","label":"Time","unit":"s"},{"key":"velocity","label":"Velocity","unit":"m/s"},{"key":"position","label":"Compatible position","unit":"m"}],"rows":[["0","4",""],["3","4",""],["5","0",""],["6","-2",""],["9","-2",""]],"series":[{"xKey":"time","yKey":"velocity","label":"Velocity-time"},{"xKey":"time","yKey":"position","label":"Position-time"}],"prompts":[{"id":"displacement","prompt":"Calculate the signed area from 0 to 9 s. (Total displacement)","type":"numeric","answer":9,"tolerance":0.05,"unit":"m"},{"id":"turning-time","prompt":"Identify when velocity crosses zero. (Turning time)","type":"numeric","answer":5,"tolerance":0.02,"unit":"s"},{"id":"text-0","prompt":"Explain how the position graph''s slope matches each velocity interval.","type":"text"}],"fit":null}'::jsonb, '{"min_rows":5}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('ea620ed5-c5d0-516c-b965-3534d21eae27', 'adaa6eeb-6eca-5fc6-a52c-30080da2d297', 'fbd_builder', 'Exercise 1B - Free-body diagram clinic — book', '{"scenario":"A book rests motionless on a horizontal table. Draw the forces acting **on the book**.","bodyLabel":"book","palette":["Weight (earth on object)","Normal force (surface on object)","Friction (surface on object)","Tension (rope on object)","Air drag (air on object)","Weight (earth on book)","Weight (earth on sled)","Weight (earth on ball)","Weight (earth on block)","Normal force (table on book)","Normal force (snow on sled)","Tension (rope on sled)","Friction (snow on sled)","Tension (rope on block)","Air drag (air on ball)","Applied force"],"target":[{"label":"Weight (earth on book)","angle":-90},{"label":"Normal force (table on book)","angle":90}],"angleTolerance":15,"hints":["I circled the system before drawing forces.","I included only forces acting on that system."]}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('ea620ed5-c5d0-516c-b965-3534d21eae27', 'adaa6eeb-6eca-5fc6-a52c-30080da2d297', 'fbd_builder', 'Exercise 1B - Free-body diagram clinic — sled', '{"scenario":"A sled is pulled along level snow by a rope angled 30° above the horizontal. Draw the forces acting **on the sled** (rope pulls to the right).","bodyLabel":"sled","palette":["Weight (earth on object)","Normal force (surface on object)","Friction (surface on object)","Tension (rope on object)","Air drag (air on object)","Weight (earth on book)","Weight (earth on sled)","Weight (earth on ball)","Weight (earth on block)","Normal force (table on book)","Normal force (snow on sled)","Tension (rope on sled)","Friction (snow on sled)","Tension (rope on block)","Air drag (air on ball)","Applied force"],"target":[{"label":"Weight (earth on sled)","angle":-90},{"label":"Normal force (snow on sled)","angle":90},{"label":"Tension (rope on sled)","angle":30},{"label":"Friction (snow on sled)","angle":180}],"angleTolerance":15,"hints":["I circled the system before drawing forces.","I included only forces acting on that system."]}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('ea620ed5-c5d0-516c-b965-3534d21eae27', 'adaa6eeb-6eca-5fc6-a52c-30080da2d297', 'fbd_builder', 'Exercise 1B - Free-body diagram clinic — falling ball', '{"scenario":"A ball falls straight down at terminal speed, so air drag balances weight. Draw the forces acting **on the ball**.","bodyLabel":"ball","palette":["Weight (earth on object)","Normal force (surface on object)","Friction (surface on object)","Tension (rope on object)","Air drag (air on object)","Weight (earth on book)","Weight (earth on sled)","Weight (earth on ball)","Weight (earth on block)","Normal force (table on book)","Normal force (snow on sled)","Tension (rope on sled)","Friction (snow on sled)","Tension (rope on block)","Air drag (air on ball)","Applied force"],"target":[{"label":"Weight (earth on ball)","angle":-90},{"label":"Air drag (air on ball)","angle":90}],"angleTolerance":15,"hints":["I circled the system before drawing forces.","I included only forces acting on that system."]}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('ea620ed5-c5d0-516c-b965-3534d21eae27', 'adaa6eeb-6eca-5fc6-a52c-30080da2d297', 'fbd_builder', 'Exercise 1B - Free-body diagram clinic — pulley block', '{"scenario":"Two blocks hang from a pulley. Choose the **rising** block and draw only the forces acting on it.","bodyLabel":"block","palette":["Weight (earth on object)","Normal force (surface on object)","Friction (surface on object)","Tension (rope on object)","Air drag (air on object)","Weight (earth on book)","Weight (earth on sled)","Weight (earth on ball)","Weight (earth on block)","Normal force (table on book)","Normal force (snow on sled)","Tension (rope on sled)","Friction (snow on sled)","Tension (rope on block)","Air drag (air on ball)","Applied force"],"target":[{"label":"Weight (earth on block)","angle":-90},{"label":"Tension (rope on block)","angle":90}],"angleTolerance":15,"hints":["I circled the system before drawing forces.","I included only forces acting on that system."]}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('ea620ed5-c5d0-516c-b965-3534d21eae27', 'adaa6eeb-6eca-5fc6-a52c-30080da2d297', 'constructed_response', 'Reflection', '{"prompt":"- Which required move prevented your first mistake?","rubric":[],"minChars":20}'::jsonb, '{"min_chars":20}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('ea1e1376-c460-5a21-bfa5-4191007b93f5', 'cdc3d5f3-5e04-5eec-ae9f-3f92f9b155fd', 'callout', 'Orientation', '{"variant":"intuition","body":"**Learning outcomes**\n- Move between physical representations.\n- Derive kinematic and constraint relationships.\n- Locate and repair the first invalid inference.\n\n**Essential questions**\n- How do modelling decisions determine which mathematics is valid?"}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('ea1e1376-c460-5a21-bfa5-4191007b93f5', 'cdc3d5f3-5e04-5eec-ae9f-3f92f9b155fd', 'rich_text', 'From descriptions to dynamical models', '{"body":"**Purpose.** This studio extends the core exposition with derivation practice, worked examples, tutorials, an investigation, computational modelling, error diagnosis, an unguided problem set, and a mastery test. Attempt every prompt before consulting the solutions volume.\n\nIntroductory mechanics becomes reliable when every problem is treated as a chain of modelling decisions rather than a hunt for a matching formula. First define the system, time interval, reference frame, and approximation. Then choose coordinates and representations. Only after this should equations be written. The same physical event can be represented by a position graph, a velocity graph, a vector diagram, a free-body diagram, or a differential equation; each representation exposes different information.\n\nKinematics is most general when written with derivatives and integrals. Velocity is $v_x=dx/dt$ and acceleration is $a_x=dv_x/dt=d^2x/dt^2$. Constant-acceleration equations are therefore special integrated cases, not independent laws. For non-constant acceleration the graph, integral, or differential equation is the correct tool. This distinction prevents one of the most common errors in first-semester physics: using a constant-acceleration identity when the force depends on position or velocity.\n\nNewtonian dynamics adds an interaction model. The statement $\\sum\\vec F_{ext}=d\\vec p/dt$ becomes $\\sum\\vec F=m\\vec a$ only for constant mass in an inertial frame. A free-body diagram is a model of interactions acting on the selected system, not a picture of everything present in the scene. The diagram must contain forces, not velocities, accelerations, energy arrows, or invented labels such as centripetal force unless a real interaction supplies that inward force.\n\nCircular motion is a particularly useful test of understanding. Constant speed does not imply zero acceleration because velocity is a vector. For uniform circular motion the acceleration magnitude is $a_c=v^2/r=\\omega^2r$ and points toward the centre. The inward net force may be tension, gravity, friction, a normal force, or a combination. Treating centripetal force as an extra force double-counts the dynamics."}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('ea1e1376-c460-5a21-bfa5-4191007b93f5', 'cdc3d5f3-5e04-5eec-ae9f-3f92f9b155fd', 'constructed_response', 'Derivation board', '{"prompt":"- From the definitions vₓ=dx/dt and aₓ=dvₓ/dt, write the definite integrals for Δx and Δv between tᵢ and t_f.\n- Explain geometrically why a velocity vector of constant magnitude in uniform circular motion has inward acceleration of magnitude v²/r=ω²r.","guidance":null,"modelAnswer":null,"rubric":[{"id":"r0","label":"My integration limits are explicit."},{"id":"r1","label":"My circular-motion explanation changes direction without changing speed."}],"minChars":20}'::jsonb, '{"min_chars":20}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('ea1e1376-c460-5a21-bfa5-4191007b93f5', 'cdc3d5f3-5e04-5eec-ae9f-3f92f9b155fd', 'worked_example_studio', 'Worked studio: Non-uniform acceleration', '{"problem":"A cart has velocity v(t)=2.0+0.80t² m/s. Find acceleration at 3.0 s and displacement from 0 to 3.0 s.","prompt":"Differentiate and integrate rather than applying constant-acceleration identities.","steps":["1. Differentiate: a(t)=1.60t, so a(3)=4.8 m/s².","2. Integrate velocity: Δx=∫₀³(2+0.8t²)dt=2t+(0.8/3)t³ evaluated from 0 to 3.","3. The displacement is 13.2 m."],"answer":"a(3.0 s)=4.8 m/s²; Δx=13.2 m.","interpretation":"The calculation uses the definitions directly; no constant-acceleration formula is valid because acceleration changes with time."}'::jsonb, '{"min_attempt_chars":12}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('ea1e1376-c460-5a21-bfa5-4191007b93f5', 'cdc3d5f3-5e04-5eec-ae9f-3f92f9b155fd', 'worked_example_studio', 'Worked studio: Horizontal curve and friction', '{"problem":"A 900 kg car moves at 15 m/s around a flat curve of radius 50 m. What minimum static-friction coefficient prevents slipping?","prompt":"Use friction as the real interaction supplying the inward force.","steps":["1. Required inward force is mv²/r.","2. The maximum static friction is μ_smg.","3. Set μ_smg≥mv²/r, giving μ_s≥v²/(rg)=0.459."],"answer":"Minimum μ_s=0.459.","interpretation":"Mass cancels. The friction is not an additional centripetal force; it is the interaction that provides the inward net force."}'::jsonb, '{"min_attempt_chars":12}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('ea1e1376-c460-5a21-bfa5-4191007b93f5', 'cdc3d5f3-5e04-5eec-ae9f-3f92f9b155fd', 'graph_table_lab', 'Tutorial A - Graph reconstruction clinic', '{"instructions":"Work in the order shown. Do not skip the prediction or representation stages: sketch an x-t graph with three intervals (increasing concave up, decreasing linear, horizontal); produce qualitative v-t and a-t graphs; mark zero velocity and positive acceleration; explain what is invariant under a shift of position origin.","columns":[{"key":"time","label":"Qualitative time","unit":"s"},{"key":"position","label":"Position","unit":"m"},{"key":"velocity","label":"Velocity","unit":"m/s"},{"key":"acceleration","label":"Acceleration","unit":"m/s^2"}],"rows":[],"series":[{"xKey":"time","yKey":"position","label":"Position-time"},{"xKey":"time","yKey":"velocity","label":"Velocity-time"},{"xKey":"time","yKey":"acceleration","label":"Acceleration-time"}],"prompts":[{"id":"text-0","prompt":"Mark every instant at which velocity is zero and every interval of positive acceleration.","type":"text"},{"id":"text-1","prompt":"Explain which features are invariant if the origin of position is shifted.","type":"text"}],"fit":null}'::jsonb, '{"min_rows":6}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('ea1e1376-c460-5a21-bfa5-4191007b93f5', 'cdc3d5f3-5e04-5eec-ae9f-3f92f9b155fd', 'constructed_response', 'Tutorial B - Constraint and force model', '{"prompt":"- **Block on the horizontal table:** The table block is connected over a frictionless pulley to a hanging block. Draw its separate free-body diagram and use the explanation to derive the constraint equation, acceleration, and tension for masses m₁ and m₂.\n- **Hanging block:** Draw the hanging block''s separate free-body diagram using a coordinate direction consistent with the rope constraint. Then explain exactly where kinetic friction changes the derivation.","guidance":"Draw each diagram on paper, then describe your diagrams and their force sources in the response.","rubric":[{"id":"r0","label":"The two acceleration coordinates obey one explicit rope constraint."},{"id":"r1","label":"The frictionless symbolic result is shown before kinetic friction is added."},{"id":"r2","label":"I identified the exact component equation changed by kinetic friction."}],"minChars":60}'::jsonb, '{"min_chars":60}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('ea1e1376-c460-5a21-bfa5-4191007b93f5', 'cdc3d5f3-5e04-5eec-ae9f-3f92f9b155fd', 'debug_task', 'Debug the solution', '{"scenario":"Locate the first invalid inference and repair the force model.","flawedSteps":["The car moves at constant speed, so acceleration is zero. Therefore the inward friction force on a circular road must also be zero."],"prompts":[{"id":"p0","prompt":"Identify the first invalid step.","minChars":15},{"id":"p1","prompt":"State the violated principle or assumption.","minChars":15},{"id":"p2","prompt":"Repair the solution from that point onward and write the correct inward force equation.","minChars":15}],"feedback":"A complete repair distinguishes constant speed from constant velocity and writes an inward acceleration v²/r supplied by a real interaction such as friction.","errorClass":"model","taxonomy":"model"}'::jsonb, '{"min_chars":15}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('ea1e1376-c460-5a21-bfa5-4191007b93f5', 'cdc3d5f3-5e04-5eec-ae9f-3f92f9b155fd', 'constructed_response', 'Reflection', '{"prompt":"- Which representation exposed the structure most clearly?","rubric":[],"minChars":20}'::jsonb, '{"min_chars":20}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('b184d8cc-d080-51d0-a9e5-ecc54761eab1', '09ab2235-36bf-541b-b1e6-d472e8844eb7', 'callout', 'Orientation', '{"variant":"intuition","body":"**Learning outcomes**\n- Calibrate and analyse position-time observations.\n- Explain uncertainty and numerical differentiation noise.\n- Validate a numerical trajectory against an analytic case.\n\n**Essential questions**\n- Where does the ideal model agree with evidence, and where does it fail?"}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('b184d8cc-d080-51d0-a9e5-ecc54761eab1', '09ab2235-36bf-541b-b1e6-d472e8844eb7', 'rich_text', 'Experimental and computational investigation', '{"body":"The investigation requires raw observations or simulation settings; a model equation; a graph; an uncertainty or numerical-error statement; comparison between prediction and result; and a brief limitations paragraph. Computational work must state initial conditions, parameter values, units, algorithm or code, step size where relevant, and a numerical or limiting-case validation."}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('b184d8cc-d080-51d0-a9e5-ecc54761eab1', '09ab2235-36bf-541b-b1e6-d472e8844eb7', 'video', 'Motion-tracking lab briefing', '{"url":null,"transcript":"## Safe setup\n\nRecord only a safe one-dimensional motion. Keep the phone stationary and the motion parallel to the image plane. Do not film traffic, heights, fast projectiles, or any setup that places a person or device at risk. You may use the bundled observations instead of a camera.\n\n## Calibration and timing\n\nPlace a ruler or known-length object in the plane of motion. Mark two calibration points and enter their real separation. Use the video''s actual frame timestamps rather than assuming a nominal frame rate.\n\n## Observations and analysis\n\nExtract at least 20 position-time points. Estimate velocity with central differences at interior points, then estimate acceleration. Compare the numerical derivative with a stated model.\n\n## Minimum evidence\n\nRetain the observations or fallback settings, model equation, graph, scale and timing uncertainty, comparison between prediction and result, explanation of how differentiation amplifies noise, and a brief limitations paragraph."}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('b184d8cc-d080-51d0-a9e5-ecc54761eab1', '09ab2235-36bf-541b-b1e6-d472e8844eb7', 'constructed_response', 'Motion-tracking briefing check', '{"prompt":"I will use a safe one-dimensional setup or the bundled fallback, calibrate distance, use actual timing, extract at least 20 observations, retain the model and graph, and explain uncertainty, derivative noise, agreement, and limitations.\n\nIn your own words, confirm the standard and how you will apply it:","modelAnswer":"I understand the investigation briefing.","rubric":[],"minChars":10}'::jsonb, '{"min_chars":10}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('b184d8cc-d080-51d0-a9e5-ecc54761eab1', '09ab2235-36bf-541b-b1e6-d472e8844eb7', 'motion_lab', 'Investigation - Video motion tracking', '{"instructions":"Record a safe one-dimensional motion with a phone at known frame rate. Calibrate distance with a ruler or known object, extract at least 20 position-time points, estimate velocity by central differences, estimate acceleration, and compare the numerical derivative with a model.\n\n**Safety:** Keep the phone stationary and away from traffic, heights, fast projectiles, and any setup that could endanger a person or device. Use the bundled data whenever capture is unavailable or unsafe.\n\nIf you cannot film a motion safely, analyse the bundled fallback observations below — the same analysis applies.","dataset":{"label":"Module 1 fallback observations","description":"Thirty-one calibrated position-time observations at 0.1 s intervals with small measurement deviations.","xUnit":"s","yUnit":"m","rows":[[0,0],[0.1,0.064],[0.2,0.127],[0.3,0.199],[0.4,0.27],[0.5,0.35],[0.6,0.434],[0.7,0.517],[0.8,0.609],[0.9,0.7],[1,0.8],[1.1,0.904],[1.2,1.007],[1.3,1.119],[1.4,1.23],[1.5,1.35],[1.6,1.474],[1.7,1.597],[1.8,1.729],[1.9,1.86],[2,2],[2.1,2.144],[2.2,2.287],[2.3,2.439],[2.4,2.59],[2.5,2.75],[2.6,2.914],[2.7,3.077],[2.8,3.249],[2.9,3.42],[3,3.6]]},"prompts":[{"id":"report-0","prompt":"Report — Model Equation:","type":"text"},{"id":"report-1","prompt":"Report — Scale Uncertainty:","type":"text"},{"id":"report-2","prompt":"Report — Timing Uncertainty:","type":"text"},{"id":"report-3","prompt":"Report — Noise Amplification:","type":"text"},{"id":"report-4","prompt":"Report — Prediction Comparison:","type":"text"},{"id":"report-5","prompt":"Report — Limitations:","type":"text"}]}'::jsonb, '{"min_points":20}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('b184d8cc-d080-51d0-a9e5-ecc54761eab1', '09ab2235-36bf-541b-b1e6-d472e8844eb7', 'sim_lab', 'Computational mini-lab - Guided numerical kinematics', '{"intro":"Integrate sampled acceleration in a structured table and quantify time-step error.\n\n**Position update:** xₙ₊₁=xₙ+vₙΔt · **Velocity update:** vₙ₊₁=vₙ+aₙΔt","model":{"kind":"kinematics_euler","dataset":[[0,0],[1,0.1],[2,0.2],[3,0.3],[4,0.4],[5,0.5],[6,0.6],[7,0.7],[8,0.8],[9,0.9],[10,1],[11,1.1],[12,1.2],[13,1.3],[14,1.4],[15,1.5],[16,1.6],[17,1.7],[18,1.8],[19,1.9],[20,2]],"defaults":{"x0":0,"v0":0.6,"dt":0.1,"tMax":20,"analyticOverlay":true}},"sliders":[{"id":"dt","label":"Time step Δt","min":0.01,"max":0.2,"step":0.01,"value":0.1,"unit":"s"},{"id":"v0","label":"Initial velocity v₀","min":0,"max":2,"step":0.1,"value":0.6,"unit":"m/s"},{"id":"x0","label":"Initial position x₀","min":0,"max":2,"step":0.1,"value":0,"unit":"m"},{"id":"tMax","label":"Run duration","min":1,"max":6,"step":0.5,"value":20,"unit":"s"}],"predictions":[{"id":"pred-error","prompt":"Predict first: will the Euler position at the final time sit above or below the analytic x(t) = x₀ + v₀t + ½at², and why?"}],"checks":[{"id":"v0","label":"State initial conditions, parameters, units, algorithm, and step size."},{"id":"v1","label":"Compare with x(t)=x₀+v₀t+½at² and v(t)=v₀+at."},{"id":"v2","label":"Quantify the final-time error."},{"id":"v3","label":"Repeat with a smaller time step."},{"id":"v4","label":"Explain the limiting-case result and why the position update has first-order time-step error."}]}'::jsonb, '{"allow_rerun":true}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('b184d8cc-d080-51d0-a9e5-ecc54761eab1', '09ab2235-36bf-541b-b1e6-d472e8844eb7', 'sim_lab', 'Computational mini-lab - Python notebook (extension)', '{"intro":"Produce the same reproducible numerical evidence with editable offline Python.\n\n**Position update:** xₙ₊₁ = xₙ + vₙΔt · **Velocity update:** vₙ₊₁ = vₙ + aₙΔt\n\n*Extension variant: explore how the time step controls the error — halve Δt and compare the final-time error, as in the validation rule.*","model":{"kind":"kinematics_euler","dataset":[[0,0],[1,0.1],[2,0.2],[3,0.3],[4,0.4],[5,0.5],[6,0.6],[7,0.7],[8,0.8],[9,0.9],[10,1],[11,1.1],[12,1.2],[13,1.3],[14,1.4],[15,1.5],[16,1.6],[17,1.7],[18,1.8],[19,1.9],[20,2]],"defaults":{"x0":0,"v0":0.6,"dt":0.1,"tMax":20,"analyticOverlay":true}},"sliders":[{"id":"dt","label":"Time step Δt","min":0.01,"max":0.2,"step":0.01,"value":0.1,"unit":"s"},{"id":"v0","label":"Initial velocity v₀","min":0,"max":2,"step":0.1,"value":0.6,"unit":"m/s"},{"id":"x0","label":"Initial position x₀","min":0,"max":2,"step":0.1,"value":0,"unit":"m"},{"id":"tMax","label":"Run duration","min":1,"max":6,"step":0.5,"value":20,"unit":"s"}],"predictions":[{"id":"pred-error","prompt":"Predict first: will the Euler position at the final time sit above or below the analytic x(t) = x₀ + v₀t + ½at², and why?"}],"checks":[]}'::jsonb, '{"allow_rerun":true}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('b184d8cc-d080-51d0-a9e5-ecc54761eab1', '09ab2235-36bf-541b-b1e6-d472e8844eb7', 'constructed_response', 'Reflection', '{"prompt":"- Which uncertainty dominates your result?","rubric":[],"minChars":20}'::jsonb, '{"min_chars":20}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('d18b4e31-7e9d-576f-a6cd-445a987368e8', 'd562b56f-ed6d-58a1-b02c-066a037ae26c', 'callout', 'Orientation', '{"variant":"intuition","body":"**Learning outcomes**\n- Solve less-scaffolded motion and force problems.\n- Derive and explain rather than merely substitute.\n- Perform a dimensional or physical check.\n\n**Essential questions**\n- Can you select the correct model without scaffolding?"}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('d18b4e31-7e9d-576f-a6cd-445a987368e8', 'd562b56f-ed6d-58a1-b02c-066a037ae26c', 'rich_text', 'Problem set', '{"body":"These problems are deliberately less scaffolded than the guided exercises. Draw a representation before calculation; solve symbolically when practical; carry units; and perform at least one check."}'::jsonb, '{}'::jsonb, 0, true)
