INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('d18b4e31-7e9d-576f-a6cd-445a987368e8', 'd562b56f-ed6d-58a1-b02c-066a037ae26c', 'exercise', 'Problem 6', '{"question_id":"9cad7021-0d82-55c7-bf33-05865f897b6a"}'::jsonb, '{"unit":"N"}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('d18b4e31-7e9d-576f-a6cd-445a987368e8', 'd562b56f-ed6d-58a1-b02c-066a037ae26c', 'constructed_response', 'Problem 7', '{"prompt":"Derive the constant-acceleration relation v_f²=v_i²+2aΔx by eliminating time.\n\nEnter the final relation, and retain the elimination steps in your working.","modelAnswer":"Begin with v_f=v_i+at and Δx=v_it+½at², solve the first for t, and substitute without introducing a new physical assumption.","rubric":[{"id":"r0","label":"The elimination steps are shown, not just the final relation."}],"minChars":30}'::jsonb, '{"min_chars":30}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('d18b4e31-7e9d-576f-a6cd-445a987368e8', 'd562b56f-ed6d-58a1-b02c-066a037ae26c', 'constructed_response', 'Problem 8', '{"prompt":"- **Box supported by a surface:** Draw weight and normal force on the box, then use the explanation field to identify the separate third-law partner of each force.","guidance":"Draw each diagram on paper, then describe your diagrams and their force sources in the response.","rubric":[{"id":"r0","label":"Weight and normal force both act on the box."},{"id":"r1","label":"The weight partner acts on Earth and the normal-force partner acts on the supporting surface."},{"id":"r2","label":"I did not call two forces on one object a third-law pair."}],"minChars":60}'::jsonb, '{"min_chars":60}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('d18b4e31-7e9d-576f-a6cd-445a987368e8', 'd562b56f-ed6d-58a1-b02c-066a037ae26c', 'exercise', 'Problem 9', '{"question_id":"2cfc074d-9545-59d9-a9c7-02bcfb0ccba9"}'::jsonb, '{"unit":"m/s^2"}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('d18b4e31-7e9d-576f-a6cd-445a987368e8', 'd562b56f-ed6d-58a1-b02c-066a037ae26c', 'constructed_response', 'Problem 10', '{"prompt":"- Construct a dimensional check for R=v₀²sin(2θ)/g.\n- State the final physical dimension and explain why the trigonometric factor is dimensionless.","guidance":null,"modelAnswer":null,"rubric":[{"id":"r0","label":"[v₀²]=L²T⁻²."},{"id":"r1","label":"[g]=LT⁻²."},{"id":"r2","label":"The ratio has dimension L and sin(2θ) is dimensionless."}],"minChars":15}'::jsonb, '{"min_chars":15}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('d18b4e31-7e9d-576f-a6cd-445a987368e8', 'd562b56f-ed6d-58a1-b02c-066a037ae26c', 'constructed_response', 'Reflection', '{"prompt":"- Categorize your first error in each problem.","rubric":[],"minChars":20}'::jsonb, '{"min_chars":20}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('68d7e5fd-08b8-5d14-a0d2-550adeda9649', '2f483580-6047-5b67-9803-5be6f4845b7f', 'callout', 'Orientation', '{"variant":"intuition","body":"**Learning outcomes**\n- Retrieve Module 1 concepts under time pressure.\n- Explain modelling and force principles in words.\n- Review errors by category before retrying.\n\n**Essential questions**\n- Can you apply the model without consulting notes?"}'::jsonb, '{}'::jsonb, 0, true)
INSERT INTO public.science_lesson_blocks (id, lesson_id, block_type, title, content_json, config_json, order_index, is_required) VALUES
  ('68d7e5fd-08b8-5d14-a0d2-550adeda9649', '2f483580-6047-5b67-9803-5be6f4845b7f', 'quiz', 'Module 1 Mastery Test', '{"quiz_slug":"m01-mastery"}'::jsonb, '{}'::jsonb, 0, true)
